#include <iostream>
#include <stack>
int main() {
    std::stack<int> s;
    s.push(3); s.push(1); s.push(4);
    s.pop();
    std::cout << s.top() << " " << s.size();
}

#include <iostream>
#include <stack>
int main() {
    std::string s = "(())";
    std::stack<char> st;
    for (char c : s)
        if (c == '(') st.push(c);
        else if (!st.empty()) st.pop();
    std::cout << st.size();
}

#include <iostream>
#include <stack>
int main() {
    int a[] = {4, 2, 5, 1};
    std::stack<int> st;
    for (int x : a) {
        while (!st.empty() && st.top() < x) st.pop();
        st.push(x);
    }
    std::cout << st.size() << " " << st.top();
}

#include <iostream>
#include <stack>
#include <string>
int main() {
    std::string s = "{[()]";
    std::stack<char> st;
    for (char c : s)
        if (c == '(' || c == '[' || c == '{') st.push(c);
        else if (!st.empty()) st.pop();
    std::cout << (st.empty() ? "balanced" : "broken");
}

#include <iostream>
#include <stack>
int main() {
    int a[] = {2, 1, 5, 3};
    std::stack<int> st;
    int pops = 0;
    for (int x : a) {
        while (!st.empty() && st.top() < x) { st.pop(); pops++; }
        st.push(x);
    }
    std::cout << pops;
}

#include <iostream>
#include <stack>
int main() {
    std::stack<int> a, b;
    for (int x : {1, 2, 3}) a.push(x);
    while (!a.empty()) { b.push(a.top()); a.pop(); }
    std::cout << b.top() << " " << a.size();
}
